style.css:
@-moz-document domain("character.ai") {
:root {
    --cai-bg: #1e1e1e;
    --cai-surface: #2b2b2b;
    --cai-text: #f5f5f5;
    --cai-accent: #6cb4ff;

    --cai-avatar-size: 96px;
    --cai-avatar-max-size: 160px;
    --cai-avatar-gap: 18px;
    --cai-msg-spacing: 12px;

    --cai-radius: 12px;
    --cai-font: system-ui, sans-serif;
    --cai-font-size: 15px;
  }

  html, body {
    background: var(--cai-bg) !important;
    color: var(--cai-text) !important;
    font-family: var(--cai-font) !important;
    font-size: var(--cai-font-size) !important;
  }

  a, button {
    color: var(--cai-accent) !important;
  }

  img.avatar,
  img[class*="avatar"],
  img[alt*="avatar"],
  img[src*="/avatar"],
  img[src*="character"],
  .avatar img,
  .profile-avatar img,
  .character-card img {
    width: var(--cai-avatar-size) !important;
    max-width: var(--cai-avatar-max-size) !important;
    height: auto !important;
    object-fit: contain !important;
    border-radius: 0 !important;
    display: inline-block !important;
  }

  .chat-container .message,
  [class*="chat"] [class*="message"],
  [class*="bubble"],
  .message {
    margin-left: calc(var(--cai-avatar-size) + var(--cai-avatar-gap)) !important;
    margin-bottom: var(--cai-msg-spacing) !important;
    max-width: calc(100% - (var(--cai-avatar-size) + 40px)) !important;
  }

  [class*="sidebar"],
  [class*="chat-list"],
  [class*="conversation-list"],
  [class*="character-info"],
  [class*="detail-pane"],
  [class*="right-panel"],
  [class*="profile-panel"] {
    display: none !important;
  }

  .chat-container, .chat {
    margin: 0 auto !important;
    max-width: 1000px !important;
  }

  [class*="card"], .card {
    background: var(--cai-surface) !important;
    color: var(--cai-text) !important;
    border-radius: var(--cai-radius) !important;
    padding: 14px 18px !important;
    margin-bottom: 16px !important;
  }
}
